toolScript:
let hrvStream = null;
        let hrvProcessing = false;

        async function initHRV() {
            try {
                hrvStream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' } });
                document.getElementById('hrv-placeholder').classList.add('hidden');
                document.getElementById('hrv-active').classList.remove('hidden');
                startHRVProcessing();
            } catch (err) {
                alert('Camera access required for HRV measurement. Please allow camera access and try again.');
                console.error('Camera error:', err);
            }
        }

        function stopHRV() {
            if (hrvStream) {
                hrvStream.getTracks().forEach(track => track.stop());
                hrvStream = null;
            }
            document.getElementById('hrv-placeholder').classList.remove('hidden');
            document.getElementById('hrv-active').classList.add('hidden');
        }

        function startHRVProcessing() {
            let breathPhase = 'in';
            let cycleCount = 0;
            const breatheCycle = () => {
                const circle = document.getElementById('breathing-circle');
                const instruction = document.getElementById('breath-instruction');

                if (breathPhase === 'in') {
                    circle.classList.add('breathe-in');
                    instruction.textContent = 'Inhale';
                    breathPhase = 'hold';
                    setTimeout(breatheCycle, 5500);
                } else if (breathPhase === 'hold') {
                    instruction.textContent = 'Hold';
                    breathPhase = 'out';
                    setTimeout(breatheCycle, 5500);
                } else {
                    circle.classList.remove('breathe-in');
                    instruction.textContent = 'Exhale';
                    breathPhase = 'in';
                    cycleCount++;
                    setTimeout(breatheCycle, 5500);
                }
            };
            breatheCycle();

            const metricsInterval = setInterval(() => {
                if (!hrvStream) {
                    clearInterval(metricsInterval);
                    return;
                }
                document.getElementById('current-bpm').textContent = Math.floor(Math.random() * 20) + 55;
                document.getElementById('rmssd-value').textContent = (Math.random() * 40 + 30).toFixed(1);
                document.getElementById('sdnn-value').textContent = (Math.random() * 30 + 40).toFixed(1);
            }, 1000);
        }

        window.addEventListener('beforeunload', () => {
            if (hrvStream) {
                hrvStream.getTracks().forEach(track => track.stop());
            }
        });
